<style>
:root {
  --brand-blue: #3861FB;
  --brand-navy: #0D1421;
  --brand-gray: #808A9D;
  --green: #16c784;
  --red: #ea3943;
  --bg: #F8FAFC;
  --bg-card: #FFFFFF;
  --border: #E2E8F0;
  --text-primary: #0D1421;
  --text-secondary: #64748B;
  --text-tertiary: #808A9D;
  --hover-row: #F1F5F9;
  --tab-active-bg: #EEF2FF;
  --tab-active-text: #3861FB;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.container { max-width: 1440px; margin: 0 auto; padding: 0 24px; }

/* Navigation */
.nav { background: var(--bg-card); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; }
.nav-inner { display: flex; align-items: center; height: 56px; gap: 32px; max-width: 1440px; margin: 0 auto; padding: 0 24px; }
.nav-logo { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 18px; color: var(--brand-navy); text-decoration: none; white-space: nowrap; }
.nav-logo svg { width: 28px; height: 28px; }
.nav-links { display: flex; gap: 4px; flex: 1; overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
.nav-links::-webkit-scrollbar { display: none; }
.nav-link { padding: 8px 12px; font-size: 13px; font-weight: 500; color: var(--text-secondary); text-decoration: none; border-radius: var(--radius-sm); white-space: nowrap; transition: color 0.15s, background 0.15s; cursor: pointer; }
.nav-link:hover { color: var(--text-primary); background: var(--hover-row); }
.nav-link.active { color: var(--tab-active-text); background: var(--tab-active-bg); }
.nav-right { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.btn { padding: 8px 16px; font-size: 13px; font-weight: 600; border-radius: var(--radius-sm); cursor: pointer; border: none; transition: all 0.15s; font-family: inherit; white-space: nowrap; }
.btn-ghost { background: transparent; color: var(--text-primary); }
.btn-ghost:hover { background: var(--hover-row); }
.btn-primary { background: var(--brand-blue); color: #fff; }
.btn-primary:hover { background: #2D4FDB; }

/* Promo Banner */
.promo-bar { background: linear-gradient(135deg, #3861FB 0%, #5B4FCF 100%); color: #fff; overflow: hidden; position: relative; }
.promo-inner { display: flex; align-items: center; height: 40px; max-width: 1440px; margin: 0 auto; padding: 0 24px; position: relative; }
.promo-slides { display: flex; transition: transform 0.5s ease; }
.promo-slide { min-width: 100%; display: flex; align-items: center; justify-content: center; gap: 8px; font-size: 13px; font-weight: 500; }
.promo-arrow { position: absolute; top: 50%; transform: translateY(-50%); width: 28px; height: 28px; border: none; background: rgba(255,255,255,0.2); color: #fff; border-radius: 50%; cursor: pointer; font-size: 14px; display: flex; align-items: center; justify-content: center; transition: background 0.15s; z-index: 2; }
.promo-arrow:hover { background: rgba(255,255,255,0.35); }
.promo-arrow.prev { left: 8px; }
.promo-arrow.next { right: 8px; }

/* AI Alerts Bar */
.ai-bar { background: var(--bg-card); border-bottom: 1px solid var(--border); }
.ai-inner { display: flex; align-items: center; gap: 12px; max-width: 1440px; margin: 0 auto; padding: 10px 24px; overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
.ai-inner::-webkit-scrollbar { display: none; }
.ai-prompt { display: flex; align-items: center; gap: 8px; padding: 6px 14px; background: var(--bg); border: 1px solid var(--border); border-radius: 20px; font-size: 12px; font-weight: 500; color: var(--text-primary); cursor: pointer; white-space: nowrap; transition: all 0.15s; }
.ai-prompt:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
.ai-prompt.primary { background: var(--tab-active-bg); border-color: var(--brand-blue); color: var(--brand-blue); font-weight: 600; }
.ai-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); animation: pulse 2s infinite; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }

/* Top Metrics Bar */
.metrics-bar { background: var(--bg-card); border-bottom: 1px solid var(--border); }
.metrics-inner { display: flex; gap: 0; max-width: 1440px; margin: 0 auto; padding: 16px 24px; }
.metric-card { flex: 1; padding: 0 20px; border-right: 1px solid var(--border); }
.metric-card:first-child { padding-left: 0; }
.metric-card:last-child { border-right: none; padding-right: 0; }
.metric-label { font-size: 11px; font-weight: 600; color: var(--text-tertiary); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 4px; }
.metric-value { font-size: 20px; font-weight: 700; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.metric-change { font-size: 12px; font-weight: 600; margin-left: 6px; }
.metric-change.up { color: var(--green); }
.metric-sub { font-size: 12px; color: var(--text-secondary); margin-top: 2px; }
.fear-indicator { display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: 12px; font-size: 12px; font-weight: 600; }
.fear-neutral { background: #FEF3C7; color: #92400E; }

/* Network Filter Tabs */
.filter-bar { background: var(--bg-card); border-bottom: 1px solid var(--border); }
.filter-inner { max-width: 1440px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; gap: 2px; overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
.filter-inner::-webkit-scrollbar { display: none; }
.filter-tab { padding: 10px 16px; font-size: 13px; font-weight: 500; color: var(--text-secondary); cursor: pointer; border: none; background: none; border-bottom: 2px solid transparent; white-space: nowrap; transition: all 0.15s; font-family: inherit; }
.filter-tab:hover { color: var(--text-primary); }
.filter-tab.active { color: var(--brand-blue); border-bottom-color: var(--brand-blue); font-weight: 600; }

/* Category Tabs */
.cat-bar { background: var(--bg-card); border-bottom: 1px solid var(--border); }
.cat-inner { max-width: 1440px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; gap: 4px; overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none; }
.cat-inner::-webkit-scrollbar { display: none; }
.cat-tab { padding: 10px 16px; font-size: 13px; font-weight: 500; color: var(--text-secondary); cursor: pointer; border: none; background: none; border-radius: var(--radius-sm); white-space: nowrap; transition: all 0.15s; font-family: inherit; }
.cat-tab:hover { color: var(--text-primary); background: var(--hover-row); }
.cat-tab.active { color: #fff; background: var(--brand-blue); }

/* Index Tracker */
.index-bar { background: var(--bg-card); border-bottom: 1px solid var(--border); }
.index-inner { max-width: 1440px; margin: 0 auto; padding: 12px 24px; display: flex; align-items: center; gap: 24px; font-size: 13px; }
.index-name { font-weight: 600; color: var(--text-primary); }
.index-symbol { color: var(--text-tertiary); font-size: 12px; margin-left: 4px; }
.index-price { font-weight: 700; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.index-changes { display: flex; gap: 16px; }
.index-chg { font-weight: 600; font-variant-numeric: tabular-nums; }
.index-chg.up { color: var(--green); }
.index-chg.down { color: var(--red); }

/* Table Controls */
.table-controls { max-width: 1440px; margin: 0 auto; padding: 16px 24px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.table-title { font-size: 18px; font-weight: 700; color: var(--text-primary); }
.table-sort { display: flex; gap: 4px; margin-left: auto; }
.sort-btn { padding: 6px 12px; font-size: 12px; font-weight: 500; color: var(--text-secondary); background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-sm); cursor: pointer; transition: all 0.15s; font-family: inherit; display: flex; align-items: center; gap: 4px; }
.sort-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
.sort-btn.active { background: var(--tab-active-bg); color: var(--brand-blue); border-color: var(--brand-blue); }
.action-btn { padding: 6px 14px; font-size: 12px; font-weight: 500; color: var(--text-secondary); background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-sm); cursor: pointer; transition: all 0.15s; font-family: inherit; display: flex; align-items: center; gap: 6px; }
.action-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
.action-btn svg { width: 14px; height: 14px; }

/* Column Toggle Dropdown */
.columns-dropdown, .filters-panel { display: none; background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-md); box-shadow: var(--shadow-md); padding: 16px; position: absolute; z-index: 50; min-width: 200px; }
.columns-dropdown.show, .filters-panel.show { display: block; }
.col-toggle-wrap { position: relative; }
.col-toggle-item { display: flex; align-items: center; gap: 8px; padding: 6px 0; font-size: 13px; cursor: pointer; }
.col-toggle-item input { accent-color: var(--brand-blue); }

.filters-panel { min-width: 280px; }
.filter-group { margin-bottom: 12px; }
.filter-group:last-child { margin-bottom: 0; }
.filter-group-label { font-size: 11px; font-weight: 600; color: var(--text-tertiary); text-transform: uppercase; margin-bottom: 6px; }
.filter-group select, .filter-group input { width: 100%; padding: 8px 10px; font-size: 13px; border: 1px solid var(--border); border-radius: var(--radius-sm); font-family: inherit; background: var(--bg); }
.filter-apply { width: 100%; margin-top: 8px; }

/* Crypto Table */
.table-wrap { max-width: 1440px; margin: 0 auto; padding: 0 24px; overflow-x: auto; -ms-overflow-style: none; }
.table-wrap::-webkit-scrollbar { display: none; }
.crypto-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.crypto-table th { padding: 10px 12px; text-align: right; font-size: 11px; font-weight: 600; color: var(--text-tertiary); text-transform: uppercase; letter-spacing: 0.3px; border-bottom: 2px solid var(--border); white-space: nowrap; cursor: pointer; user-select: none; transition: color 0.15s; }
.crypto-table th:hover { color: var(--brand-blue); }
.crypto-table th:first-child, .crypto-table td:first-child { text-align: center; padding-left: 8px; padding-right: 8px; }
.crypto-table th:nth-child(2), .crypto-table td:nth-child(2) { text-align: left; }
.crypto-table td { padding: 12px; text-align: right; border-bottom: 1px solid var(--border); font-variant-numeric: tabular-nums; white-space: nowrap; }
.crypto-table tbody tr { transition: background 0.1s; }
.crypto-table tbody tr:hover { background: var(--hover-row); }
.crypto-table .rank { font-size: 12px; color: var(--text-tertiary); font-weight: 500; }
.crypto-table .name-cell { display: flex; align-items: center; gap: 10px; }
.crypto-table .coin-icon { width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 700; color: #fff; flex-shrink: 0; }
.crypto-table .coin-name { font-weight: 600; color: var(--text-primary); }
.crypto-table .coin-symbol { font-size: 11px; color: var(--text-tertiary); margin-left: 4px; }
.crypto-table .price { font-weight: 600; color: var(--text-primary); }
.crypto-table .change { font-weight: 600; }
.crypto-table .change.up { color: var(--green); }
.crypto-table .change.down { color: var(--red); }
.crypto-table .change.neutral { color: var(--text-secondary); }
.crypto-table .market-cap, .crypto-table .volume { color: var(--text-primary); }
.crypto-table .supply { color: var(--text-secondary); font-size: 12px; }
.crypto-table .sparkline svg { width: 80px; height: 28px; }
.sparkline-up { stroke: var(--green); }
.sparkline-down { stroke: var(--red); }
.sparkline-neutral { stroke: var(--text-tertiary); }

/* Pagination */
.pagination { display: flex; align-items: center; justify-content: center; gap: 4px; padding: 20px 24px; max-width: 1440px; margin: 0 auto; }
.pagination .page-btn { width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--bg-card); cursor: pointer; font-size: 13px; font-weight: 500; color: var(--text-secondary); transition: all 0.15s; font-family: inherit; }
.pagination .page-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }
.pagination .page-btn.active { background: var(--brand-blue); color: #fff; border-color: var(--brand-blue); }
.pagination .page-info { font-size: 12px; color: var(--text-tertiary); margin-left: 12px; }

/* Market Summary */
.market-summary { max-width: 1440px; margin: 0 auto; padding: 32px 24px; }
.summary-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 24px; box-shadow: var(--shadow-sm); }
.summary-title { font-size: 16px; font-weight: 700; margin-bottom: 12px; }
.summary-text { font-size: 14px; color: var(--text-secondary); line-height: 1.7; }
.summary-more { color: var(--brand-blue); font-weight: 600; cursor: pointer; font-size: 13px; margin-top: 8px; display: inline-flex; align-items: center; gap: 4px; transition: color 0.15s; }
.summary-more:hover { color: #2D4FDB; }
.summary-expanded { display: none; margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--border); }
.summary-expanded.show { display: block; }
.summary-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; }
.summary-stat-label { font-size: 11px; font-weight: 600; color: var(--text-tertiary); text-transform: uppercase; }
.summary-stat-value { font-size: 16px; font-weight: 700; margin-top: 2px; }
.summary-stat-sub { font-size: 12px; color: var(--text-secondary); margin-top: 2px; }

/* Info Content */
.info-content { max-width: 1440px; margin: 0 auto; padding: 0 24px 32px; }
.info-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; }
.info-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 24px; }
.info-card h3 { font-size: 15px; font-weight: 700; margin-bottom: 8px; }
.info-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }

/* Footer */
.footer { background: var(--brand-navy); color: #94A3B8; padding: 48px 0 32px; }
.footer-inner { max-width: 1440px; margin: 0 auto; padding: 0 24px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 32px; margin-bottom: 32px; }
.footer-col h4 { font-size: 13px; font-weight: 700; color: #fff; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; }
.footer-col a { display: block; font-size: 13px; color: #94A3B8; text-decoration: none; padding: 4px 0; transition: color 0.15s; }
.footer-col a:hover { color: #fff; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 20px; font-size: 12px; text-align: center; }

/* Responsive */
@media (max-width: 1024px) {
  .nav-links { gap: 0; }
  .nav-link { padding: 8px 10px; font-size: 12px; }
  .metrics-inner { flex-wrap: wrap; }
  .metric-card { flex: 0 0 50%; padding: 10px 12px; border-right: none; border-bottom: 1px solid var(--border); }
  .metric-card:nth-child(odd) { padding-left: 0; }
  .crypto-table { font-size: 12px; }
  .crypto-table th, .crypto-table td { padding: 8px 6px; }
}
@media (max-width: 768px) {
  .nav-inner { flex-wrap: wrap; height: auto; padding: 8px 16px; gap: 8px; }
  .nav-right { width: 100%; justify-content: flex-end; }
  .metrics-inner { padding: 12px 16px; }
  .metric-value { font-size: 16px; }
  .table-controls { padding: 12px 16px; }
  .table-title { font-size: 16px; }
  .container, .table-wrap, .metrics-bar .metrics-inner, .index-inner, .filter-inner, .cat-inner, .info-content, .footer-inner, .market-summary { padding-left: 16px; padding-right: 16px; }
}
@media (max-width: 480px) {
  .metric-card { flex: 0 0 100%; }
  .pagination { gap: 2px; }
  .pagination .page-btn { width: 30px; height: 30px; font-size: 11px; }
}
</style>
</head>
