<script>
// ===== CRYPTO DATA =====
const coinColors = ['#3861FB','#627EEA','#26A17B','#23292F','#F3BA2F','#E84142','#9945FF','#82C43C','#4A90E2','#F6851B','#2775CA','#E6007A','#1E88E5','#FF6B6B','#00D18C'];

const topCoins = [
