  { rank:2, name:'Ethereum', symbol:'ETH', price:2356.00, change1h:0.51, change24h:0.80, change7d:6.29, marketCap:284350000000, volume:21360000000, supply:'120.69M ETH', supplyRaw:120690000, trend:'up' },
  { rank:3, name:'Tether', symbol:'USDT', price:1.00, change1h:0.01, change24h:0.03, change7d:0.01, marketCap:185840000000, volume:138790000000, supply:'185.8B USDT', supplyRaw:185800000000, trend:'neutral' },
  { rank:4, name:'XRP', symbol:'XRP', price:1.44, change1h:0.71, change24h:2.71, change7d:7.89, marketCap:89130000000, volume:4030000000, supply:'61.56B XRP', supplyRaw:61560000000, trend:'up' },
  { rank:5, name:'BNB', symbol:'BNB', price:632.59, change1h:0.38, change24h:1.89, change7d:4.98, marketCap:85270000000, volume:1950000000, supply:'134.78M BNB', supplyRaw:134780000, trend:'up' },
  { rank:6, name:'USD Coin', symbol:'USDC', price:0.9998, change1h:-0.01, change24h:0.01, change7d:-0.02, marketCap:56120000000, volume:8760000000, supply:'56.13B USDC', supplyRaw:56130000000, trend:'neutral' },
  { rank:7, name:'Solana', symbol:'SOL', price:88.25, change1h:0.67, change24h:3.74, change7d:5.67, marketCap:50770000000, volume:6710000000, supply:'575.26M SOL', supplyRaw:575260000, trend:'up' },
];

const moreCoinNames = [
  ['Cardano','ADA'],['Avalanche','AVAX'],['Dogecoin','DOGE'],['TRON','TRX'],['Polkadot','DOT'],
  ['Chainlink','LINK'],['Polygon','MATIC'],['Shiba Inu','SHIB'],['Litecoin','LTC'],['Bitcoin Cash','BCH'],
  ['Uniswap','UNI'],['Stellar','XLM'],['Monero','XMR'],['Cosmos','ATOM'],['Ethereum Classic','ETC'],
  ['Filecoin','FIL'],['Aptos','APT'],['Arbitrum','ARB'],['Optimism','OP'],['Sui','SUI'],
  ['Render','RNDR'],['Injective','INJ'],['Celestia','TIA'],['Sei','SEI'],['Stacks','STX'],
  ['Immutable','IMX'],['Theta','THETA'],['Aave','AAVE'],['Algorand','ALGO'],['Flow','FLOW'],
  ['Maker','MKR'],['Tezos','XTZ'],['MultiversX','EGLD'],['ApeCoin','APE'],['Axie Infinity','AXS'],
  ['The Sandbox','SAND'],['Decentraland','MANA'],['Chiliz','CHZ'],['EOS','EOS'],['IOTA','IOTA'],
  ['Neo','NEO'],['Kava','KAVA'],['Zilliqa','ZIL'],['Waves','WAVES'],['1inch','1INCH'],
  ['Curve DAO','CRV'],['PancakeSwap','CAKE'],['Astar','ASTR'],['Klaytn','KLAY'],['Mina','MINA'],
  ['Livepeer','LPT'],['Gala','GALA'],['dYdX','DYDX'],['Enjin','ENJ'],['Compound','COMP'],
  ['Synthetix','SNX'],['Helium','HNT'],['SKALE','SKL'],['Kusama','KSM'],['Dash','DASH'],
  ['Zcash','ZEC'],['Qtum','QTUM'],['ICON','ICX'],['0x Protocol','ZRX'],['Basic Attention','BAT'],
  ['Audius','AUDIO'],['Loopring','LRC'],['Storj','STORJ'],['Ankr','ANKR'],['Band Protocol','BAND'],
  ['Balancer','BAL'],['SushiSwap','SUSHI'],['yearn.finance','YFI'],['Convex Finance','CVX'],['Rocket Pool','RPL'],
  ['GMX','GMX'],['Frax Share','FXS'],['Mask Network','MASK'],['SafePal','SFP'],['Ontology','ONT'],
  ['WOO Network','WOO'],['Celo','CELO'],['Ravencoin','RVN'],['Reserve Rights','RSR'],['UMA','UMA'],
  ['Cartesi','CTSI'],['Numeraire','NMR'],['COTI','COTI'],['Dent','DENT'],['Holo','HOT'],
  ['Siacoin','SC'],['DigiByte','DGB'],['Verge','XVG'],['Polymesh','POLYX'],['JOE','JOE'],
  ['Orca','ORCA'],['Raydium','RAY'],['Bonk','BONK'],['Jupiter','JUP'],['Pyth Network','PYTH'],
];

function generateCoinData(base, idx) {
  const [name, symbol] = moreCoinNames[idx];
  const rank = base + idx;
  const basePrice = Math.exp(Math.log(0.001) + Math.random() * Math.log(10000));
  const price = Math.round(basePrice * 1000000) / 1000000;
  const ch1 = parseFloat((Math.random() * 16 - 8).toFixed(2));
  const ch24 = parseFloat((Math.random() * 24 - 12).toFixed(2));
  const ch7 = parseFloat((Math.random() * 40 - 20).toFixed(2));
  const mcap = Math.round(price * (Math.random() * 5e10 + 1e7));
  const vol = Math.round(mcap * (Math.random() * 0.5 + 0.02));
  const supplyNum = Math.round(Math.random() * 1e12 + 1e6);
  const supplyStr = supplyNum > 1e9 ? (supplyNum/1e9).toFixed(2)+'B '+symbol :
                    supplyNum > 1e6 ? (supplyNum/1e6).toFixed(2)+'M '+symbol :
                    supplyNum.toLocaleString()+' '+symbol;
  const trend = ch7 > 1 ? 'up' : ch7 < -1 ? 'down' : 'neutral';

  return {
    rank: rank + 1,
    name, symbol,
    price: price < 1 ? Math.round(price * 1e8) / 1e8 : Math.round(price * 100) / 100,
    change1h: ch1, change24h: ch24, change7d: ch7,
    marketCap: mcap, volume: vol,
    supply: supplyStr, supplyRaw: supplyNum,
    trend
  };
}

const allCoins = [...topCoins];
for (let i = 0; i < 93; i++) {
  allCoins.push(generateCoinData(7, i));
}

// ===== SPARKLINE GENERATOR =====
function generateSparkline(trend) {
  const w = 80, h = 28;
  const points = 7;
  const pad = 4;
  let values = [];
  const rng = trend === 'up' ? [0, 1] : trend === 'down' ? [-1, 0] : [-0.5, 0.5];

  let v = Math.random();
  for (let i = 0; i < points; i++) {
    v = Math.max(0.05, Math.min(0.95, v + (Math.random() - 0.5) * 0.25 + (rng[0] + Math.random() * (rng[1] - rng[0])) * 0.15));
    values.push(v);
  }

  const stepX = (w - pad * 2) / (points - 1);
  const yRange = h - pad * 2;
  let d = '';
  values.forEach((val, i) => {
    const x = pad + i * stepX;
    const y = pad + yRange - (val * yRange);
    d += (i === 0 ? 'M' : 'L') + x.toFixed(1) + ' ' + y.toFixed(1);
  });

  const lastVal = values[values.length - 1];
  const firstVal = values[0];
  const isUp = lastVal >= firstVal;
  const cls = trend === 'neutral' ? 'sparkline-neutral' : (isUp ? 'sparkline-up' : 'sparkline-down');

  return `<svg viewBox="0 0 ${w} ${h}" fill="none"><path d="${d}" class="${cls}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${(pad + (points-1)*stepX).toFixed(1)}" cy="${(pad + yRange - (lastVal * yRange)).toFixed(1)}" r="2.5" class="${cls}"/></svg>`;
}

// ===== FORMATTING =====
function formatUSD(val) {
  if (val >= 1e12) return '$' + (val / 1e12).toFixed(2) + 'T';
  if (val >= 1e9) return '$' + (val / 1e9).toFixed(2) + 'B';
  if (val >= 1e6) return '$' + (val / 1e6).toFixed(2) + 'M';
  return '$' + val.toLocaleString('en-US', {minimumFractionDigits:2,maximumFractionDigits:2});
}

function formatPrice(val) {
  if (val >= 1000) return '$' + val.toLocaleString('en-US', {minimumFractionDigits:2,maximumFractionDigits:2});
  if (val >= 1) return '$' + val.toFixed(2);
  if (val >= 0.01) return '$' + val.toFixed(4);
  return '$' + val.toFixed(8);
}

function formatChange(val) {
  const cls = val > 0 ? 'up' : val < 0 ? 'down' : 'neutral';
  const sign = val > 0 ? '+' : '';
  return `<span class="change ${cls}">${sign}${val.toFixed(2)}%</span>`;
}

function getCoinIcon(name, idx) {
  const colors = coinColors;
  const initials = name.substring(0, 2).toUpperCase();
  const bg = colors[idx % colors.length];
  return `<span class="coin-icon" style="background:${bg};">${initials[0]}</span>`;
}

// ===== RENDER TABLE =====
let currentPage = 1;
const rowsPerPage = 100;
let currentCategory = 'top';
let currentNetwork = 'all';
let currentSort = { field: 'rank', asc: true };
let visibleColumns = {
  rank: true, name: true, price: true, change1h: true, change24h: true,
  change7d: true, marketCap: true, volume: true, supply: true, sparkline: true
};

function getFilteredCoins() {
  let coins = [...allCoins];

  // Category filter simulation
  if (currentCategory === 'trending') coins = coins.sort(() => Math.random() - 0.5);
  else if (currentCategory === 'watchlist') coins = coins.filter((_, i) => i < 20);
  else if (currentCategory === 'new') coins = coins.filter((_, i) => i >= 80);
  else if (currentCategory === 'prediction') coins = coins.filter((_, i) => i % 3 === 0);
  else if (currentCategory === 'visited') coins = coins.sort((a, b) => b.volume - a.volume);

  // Network filter simulation
  if (currentNetwork === 'bsc') coins = coins.filter((_, i) => i % 5 === 0);
  else if (currentNetwork === 'solana') coins = coins.filter((_, i) => i % 5 === 1);
  else if (currentNetwork === 'base') coins = coins.filter((_, i) => i % 5 === 2);
  else if (currentNetwork === 'ethereum') coins = coins.filter((_, i) => i % 5 === 3);

  // Sort
  const field = currentSort.field;
  coins.sort((a, b) => {
    let va, vb;
    if (field === 'name') { va = a.name; vb = b.name; return currentSort.asc ? va.localeCompare(vb) : vb.localeCompare(va); }
    if (field === 'rank') { va = a.rank; vb = b.rank; }
    else if (field === 'price') { va = a.price; vb = b.price; }
    else if (field === 'change1h') { va = a.change1h; vb = b.change1h; }
    else if (field === 'change24h') { va = a.change24h; vb = b.change24h; }
    else if (field === 'change7d') { va = a.change7d; vb = b.change7d; }
    else if (field === 'marketCap') { va = a.marketCap; vb = b.marketCap; }
    else if (field === 'volume') { va = a.volume; vb = b.volume; }
    else if (field === 'supply') { va = a.supplyRaw; vb = b.supplyRaw; }
    else { va = a.rank; vb = b.rank; }
    return currentSort.asc ? va - vb : vb - va;
  });

  return coins;
}

function renderTable() {
  const coins = getFilteredCoins();
  const start = (currentPage - 1) * rowsPerPage;
  const pageCoins = coins.slice(start, start + rowsPerPage);
  const tbody = document.getElementById('tableBody');
  const thead = document.getElementById('cryptoTable').querySelector('thead');

  // Update header visibility
  thead.querySelectorAll('th').forEach(th => {
    const col = th.dataset.col;
    if (col && visibleColumns[col] !== undefined) {
      th.style.display = visibleColumns[col] ? '' : 'none';
    }
  });

  tbody.innerHTML = pageCoins.map((coin, i) => `
    <tr>
      ${visibleColumns.rank ? `<td><span class="rank">${coin.rank}</span></td>` : ''}
      ${visibleColumns.name ? `<td><div class="name-cell">${getCoinIcon(coin.name, coin.rank-1)}<span class="coin-name">${coin.name}<span class="coin-symbol">${coin.symbol}</span></span></div></td>` : ''}
      ${visibleColumns.price ? `<td><span class="price">${formatPrice(coin.price)}</span></td>` : ''}
      ${visibleColumns.change1h ? `<td>${formatChange(coin.change1h)}</td>` : ''}
      ${visibleColumns.change24h ? `<td>${formatChange(coin.change24h)}</td>` : ''}
      ${visibleColumns.change7d ? `<td>${formatChange(coin.change7d)}</td>` : ''}
      ${visibleColumns.marketCap ? `<td class="market-cap">${formatUSD(coin.marketCap)}</td>` : ''}
      ${visibleColumns.volume ? `<td class="volume">${formatUSD(coin.volume)}</td>` : ''}
      ${visibleColumns.supply ? `<td class="supply">${coin.supply}</td>` : ''}
      ${visibleColumns.sparkline ? `<td class="sparkline">${generateSparkline(coin.trend)}</td>` : ''}
    </tr>
  `).join('');

  renderPagination(coins.length);
  document.getElementById('pageInfo').textContent =
    `Showing ${start+1}–${Math.min(start+rowsPerPage, coins.length)} of ${coins.length} assets`;
}

function renderPagination(totalCoins) {
  const totalPages = Math.ceil(totalCoins / rowsPerPage);
  const pagDiv = document.getElementById('pagination');
  let html = '';

  // Previous
  html += `<button class="page-btn" onclick="goToPage(${currentPage - 1})" ${currentPage === 1 ? 'disabled style="opacity:0.4;"' : ''}>&#8249;</button>`;

  // Page numbers
  const maxPages = 7;
  let startPage = Math.max(1, currentPage - Math.floor(maxPages / 2));
  let endPage = Math.min(totalPages, startPage + maxPages - 1);
  if (endPage - startPage < maxPages - 1) startPage = Math.max(1, endPage - maxPages + 1);

  if (startPage > 1) { html += `<button class="page-btn" onclick="goToPage(1)">1</button>`; if (startPage > 2) html += `<span style="padding:0 4px;color:var(--text-tertiary);">...</span>`; }

  for (let p = startPage; p <= endPage; p++) {
    html += `<button class="page-btn${p === currentPage ? ' active' : ''}" onclick="goToPage(${p})">${p}</button>`;
  }

  if (endPage < totalPages) { if (endPage < totalPages - 1) html += `<span style="padding:0 4px;color:var(--text-tertiary);">...</span>`; html += `<button class="page-btn" onclick="goToPage(${totalPages})">${totalPages}</button>`; }

  // Next
  html += `<button class="page-btn" onclick="goToPage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled style="opacity:0.4;"' : ''}>&#8250;</button>`;

  pagDiv.innerHTML = html;
}

function goToPage(page) {
  const coins = getFilteredCoins();
  const totalPages = Math.ceil(coins.length / rowsPerPage);
  if (page < 1 || page > totalPages) return;
  currentPage = page;
  renderTable();
  document.querySelector('.table-wrap').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function sortTable(field) {
  if (currentSort.field === field) {
    currentSort.asc = !currentSort.asc;
  } else {
    currentSort.field = field;
    currentSort.asc = field === 'rank' ? true : false;
  }
  currentPage = 1;
  renderTable();

  // Update sort button states
  document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
}

// ===== COLUMN TOGGLE =====
function toggleColumns() {
  const dd = document.getElementById('columnsDropdown');
  dd.classList.toggle('show');
  document.getElementById('filtersPanel').classList.remove('show');
}

function toggleColumn(checkbox) {
  visibleColumns[checkbox.dataset.col] = checkbox.checked;
  renderTable();
}

function toggleFilters() {
  const fp = document.getElementById('filtersPanel');
  fp.classList.toggle('show');
  document.getElementById('columnsDropdown').classList.remove('show');
}

function applyFilters() {
  document.getElementById('filtersPanel').classList.remove('show');
  currentPage = 1;
  renderTable();
}

// ===== CATEGORY TABS =====
document.getElementById('categoryTabs').addEventListener('click', function(e) {
  if (e.target.classList.contains('cat-tab')) {
    this.querySelectorAll('.cat-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    currentCategory = e.target.dataset.category;
    currentPage = 1;
    renderTable();
  }
});

// ===== NETWORK FILTER TABS =====
document.getElementById('networkFilters').addEventListener('click', function(e) {
  if (e.target.classList.contains('filter-tab')) {
    this.querySelectorAll('.filter-tab').forEach(t => t.classList.remove('active'));
    e.target.classList.add('active');
    currentNetwork = e.target.dataset.network;
    currentPage = 1;
    renderTable();
  }
});

// ===== NAV LINKS =====
document.querySelectorAll('.nav-link').forEach(link => {
  link.addEventListener('click', function() {
    document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));
    this.classList.add('active');
  });
});

// ===== PROMO CAROUSEL =====
let promoIndex = 0;
const promoScreens = 3;
function movePromo(dir) {
  promoIndex = (promoIndex + dir + promoScreens) % promoScreens;
  document.getElementById('promoSlides').style.transform = `translateX(-${promoIndex * 100}%)`;
}
setInterval(() => movePromo(1), 5000);

// ===== MARKET SUMMARY ACCORDION =====
function toggleSummary() {
  const expanded = document.getElementById('summaryExpanded');
  const btn = document.getElementById('readMoreBtn');
  const isOpen = expanded.classList.toggle('show');
  btn.innerHTML = isOpen
    ? 'Read Less <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 10L8 6l-4 4"/></svg>'
    : 'Read More <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6l4 4 4-4"/></svg>';
}

// ===== CLOSE DROPDOWNS ON OUTSIDE CLICK =====
document.addEventListener('click', function(e) {
  if (!e.target.closest('.col-toggle-wrap')) document.getElementById('columnsDropdown').classList.remove('show');
  if (!e.target.closest('#filtersToggle') && !e.target.closest('#filtersPanel') && !e.target.closest('.filter-apply')) {
    document.getElementById('filtersPanel').classList.remove('show');
  }
});

// ===== SORT BUTTONS =====
document.querySelectorAll('.sort-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    sortTable(this.dataset.sort);
  });
});

// ===== KEYBOARD NAVIGATION =====
document.addEventListener('keydown', function(e) {
  if (e.key === 'ArrowLeft' && !e.target.closest('input,select,textarea')) goToPage(currentPage - 1);
  if (e.key === 'ArrowRight' && !e.target.closest('input,select,textarea')) goToPage(currentPage + 1);
  if (e.key === 'Escape') {
    document.getElementById('columnsDropdown').classList.remove('show');
    document.getElementById('filtersPanel').classList.remove('show');
  }
});

// ===== INITIAL RENDER =====
renderTable();
</script>

</body>
</html>
